-- Pedido da Casa: schema inicial. Executar no Supabase > SQL Editor.
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,is_admin boolean not null default false,created_at timestamptz not null default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,email,is_admin) values(new.id,new.email,false) on conflict(id) do update set email=excluded.email; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles p where p.id=auth.uid() and p.is_admin=true); $$;
create table if not exists public.categories(id uuid primary key default gen_random_uuid(),name text not null,sort_order int not null default 0,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),category_id uuid references public.categories(id) on delete set null,name text not null,description text not null default '',price numeric(10,2) not null check(price>=0),image_url text,ingredients text[] not null default '{}',sort_order int not null default 0,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.addons(id uuid primary key default gen_random_uuid(),name text not null,price numeric(10,2) not null default 0 check(price>=0),active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.store_settings(id int primary key default 1 check(id=1),store_name text not null default 'Pedido da Casa',delivery_fee numeric(10,2) not null default 0 check(delivery_fee>=0),is_open boolean not null default true,address text not null default '',opening_hours text not null default '',updated_at timestamptz not null default now());
insert into public.store_settings(id) values(1) on conflict(id) do nothing;
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),customer_name text not null,customer_phone text not null,fulfillment text not null check(fulfillment in('pickup','delivery')),address text not null default '',payment_method text not null check(payment_method in('pix','cash','card')),cash_change_for numeric(10,2),notes text not null default '',status text not null default 'received' check(status in('received','accepted','preparing','ready','completed','rejected')),subtotal numeric(10,2) not null default 0,delivery_fee numeric(10,2) not null default 0,total numeric(10,2) not null default 0,print_status text not null default 'not_printed' check(print_status in('not_printed','print_dialog_opened','printed','failed')),created_at timestamptz not null default now());
create table if not exists public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid references public.products(id) on delete set null,product_name_snapshot text not null,unit_price numeric(10,2) not null,quantity int not null check(quantity>0 and quantity<=50),addon_names_snapshot text[] not null default '{}',removed_ingredients text[] not null default '{}',notes text not null default '',line_total numeric(10,2) not null);
alter table public.profiles enable row level security; alter table public.categories enable row level security; alter table public.products enable row level security; alter table public.addons enable row level security; alter table public.store_settings enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security;
revoke all on public.profiles,public.categories,public.products,public.addons,public.store_settings,public.orders,public.order_items from anon,authenticated;
grant select on public.categories,public.products,public.addons,public.store_settings to anon,authenticated; grant select,insert,update,delete on public.categories,public.products,public.addons,public.store_settings to authenticated; grant select on public.orders,public.order_items to authenticated; grant update on public.orders to authenticated;
drop policy if exists public_read_categories on public.categories; create policy public_read_categories on public.categories for select to anon,authenticated using(active or public.is_admin());
drop policy if exists public_read_products on public.products; create policy public_read_products on public.products for select to anon,authenticated using(active or public.is_admin());
drop policy if exists public_read_addons on public.addons; create policy public_read_addons on public.addons for select to anon,authenticated using(active or public.is_admin());
drop policy if exists public_read_settings on public.store_settings; create policy public_read_settings on public.store_settings for select to anon,authenticated using(true);
drop policy if exists admins_categories on public.categories; create policy admins_categories on public.categories for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists admins_products on public.products; create policy admins_products on public.products for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists admins_addons on public.addons; create policy admins_addons on public.addons for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists admins_settings on public.store_settings; create policy admins_settings on public.store_settings for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists admins_orders_read on public.orders; create policy admins_orders_read on public.orders for select to authenticated using(public.is_admin());
drop policy if exists admins_orders_update on public.orders; create policy admins_orders_update on public.orders for update to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists admins_items_read on public.order_items; create policy admins_items_read on public.order_items for select to authenticated using(public.is_admin());
drop policy if exists profile_read_self on public.profiles; create policy profile_read_self on public.profiles for select to authenticated using(id=auth.uid() or public.is_admin());
-- O navegador nunca define preço total: função calcula preço e grava pedido numa transação.
create or replace function public.create_public_order(order_data jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare oid uuid; sub numeric(10,2):=0; fee numeric(10,2):=0; totalv numeric(10,2):=0; item jsonb; prod public.products%rowtype; qty int; aid uuid[]; atotal numeric(10,2); anames text[]; unitv numeric(10,2); linev numeric(10,2); cname text; phone text; fulfill text; addr text; pay text; changev numeric(10,2); notesv text; openv boolean;
begin
cname:=left(trim(coalesce(order_data->>'customer_name','')),120); phone:=left(regexp_replace(coalesce(order_data->>'customer_phone',''),'[^0-9+]','','g'),25); fulfill:=coalesce(order_data->>'fulfillment','pickup'); addr:=left(trim(coalesce(order_data->>'address','')),400); pay:=coalesce(order_data->>'payment_method','pix'); changev:=nullif(order_data->>'cash_change_for','')::numeric; notesv:=left(trim(coalesce(order_data->>'notes','')),1000);
if length(cname)<2 then raise exception 'Informe o nome.'; end if; if length(phone)<8 then raise exception 'Informe um telefone válido.'; end if; if fulfill not in('pickup','delivery') then raise exception 'Recebimento inválido.'; end if; if fulfill='delivery' and length(addr)<5 then raise exception 'Informe o endereço.'; end if; if pay not in('pix','cash','card') then raise exception 'Pagamento inválido.'; end if; if jsonb_typeof(order_data->'items')<>'array' or jsonb_array_length(order_data->'items')<1 or jsonb_array_length(order_data->'items')>40 then raise exception 'Carrinho inválido.'; end if;
select is_open,delivery_fee into openv,fee from public.store_settings where id=1; if coalesce(openv,false)=false then raise exception 'A lanchonete está fechada.'; end if; if fulfill='pickup' then fee:=0; end if;
insert into public.orders(customer_name,customer_phone,fulfillment,address,payment_method,cash_change_for,notes,delivery_fee) values(cname,phone,fulfill,addr,pay,case when pay='cash' then changev else null end,notesv,fee) returning id into oid;
for item in select value from jsonb_array_elements(order_data->'items') loop select * into prod from public.products where id=(item->>'product_id')::uuid and active=true; if not found then raise exception 'Produto indisponível.'; end if; qty:=greatest(1,least(50,coalesce((item->>'quantity')::int,1))); aid:=array(select jsonb_array_elements_text(coalesce(item->'addon_ids','[]'::jsonb))::uuid); select coalesce(sum(a.price),0),coalesce(array_agg(a.name order by a.name),array[]::text[]) into atotal,anames from public.addons a where a.id=any(aid) and a.active=true; unitv:=prod.price+atotal; linev:=unitv*qty; insert into public.order_items(order_id,product_id,product_name_snapshot,unit_price,quantity,addon_names_snapshot,removed_ingredients,notes,line_total) values(oid,prod.id,prod.name,unitv,qty,anames,array(select jsonb_array_elements_text(coalesce(item->'removed_ingredients','[]'::jsonb))),left(coalesce(item->>'notes',''),500),linev); sub:=sub+linev; end loop;
totalv:=sub+fee; update public.orders set subtotal=sub,total=totalv where id=oid; return jsonb_build_object('order_id',oid,'subtotal',sub,'delivery_fee',fee,'total',totalv); end; $$;
revoke all on function public.create_public_order(jsonb) from public; grant execute on function public.create_public_order(jsonb) to anon,authenticated;
insert into public.categories(name,sort_order) select 'Hambúrgueres',1 where not exists(select 1 from public.categories where name='Hambúrgueres'); insert into public.categories(name,sort_order) select 'Porções',2 where not exists(select 1 from public.categories where name='Porções'); insert into public.categories(name,sort_order) select 'Bebidas',3 where not exists(select 1 from public.categories where name='Bebidas');
insert into public.products(name,description,price,category_id,sort_order) select 'X-Burger','Hambúrguer, queijo e molho da casa.',18.90,id,1 from public.categories where name='Hambúrgueres' and not exists(select 1 from public.products where name='X-Burger'); insert into public.products(name,description,price,category_id,sort_order) select 'X-Bacon','Hambúrguer, queijo e bacon crocante.',23.90,id,2 from public.categories where name='Hambúrgueres' and not exists(select 1 from public.products where name='X-Bacon'); insert into public.products(name,description,price,category_id,sort_order) select 'Batata frita','Porção dourada e crocante.',14,id,1 from public.categories where name='Porções' and not exists(select 1 from public.products where name='Batata frita'); insert into public.products(name,description,price,category_id,sort_order) select 'Refrigerante lata','Lata 350 ml.',6,id,1 from public.categories where name='Bebidas' and not exists(select 1 from public.products where name='Refrigerante lata'); insert into public.addons(name,price) select 'Bacon extra',4 where not exists(select 1 from public.addons where name='Bacon extra'); insert into public.addons(name,price) select 'Queijo extra',3 where not exists(select 1 from public.addons where name='Queijo extra');
